import os
import re

paper_dir = "/home/ubuntu/.agent-ml-research-idea_gen_0514_3/projects/gen-depth-fingerprint/artifacts/_project/paper"

# Comprehensive blacklist
blacklist_patterns = {
    'delve': (r'\bdelve\b', 'word'),
    'leverage': (r'\bleverage\b', 'word'),
    'utilize': (r'\butilize\b', 'word'),
    'facilitate': (r'\bfacilitate\b', 'word'),
    'myriad': (r'\bmyriad\b', 'word'),
    'plethora': (r'\bplethora\b', 'word'),
    'paradigm shift': (r'paradigm shift', 'phrase'),
    'It is worth noting': (r'It is worth noting', 'phrase'),
}

results = {k: [] for k in blacklist_patterns}

tex_files = sorted([f for f in os.listdir(paper_dir) if f.endswith('.tex')])

for tex_file in tex_files:
    filepath = os.path.join(paper_dir, tex_file)
    try:
        with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
            lines = f.readlines()

        for i, line in enumerate(lines, 1):
            for pattern_name, (pattern_regex, ptype) in blacklist_patterns.items():
                if re.search(pattern_regex, line, re.IGNORECASE):
                    results[pattern_name].append((tex_file, i, line.strip()))
    except:
        pass

print("=== Blacklisted Words/Phrases ===\n")
found_any = False
for pattern_name in sorted(blacklist_patterns.keys()):
    count = len(results[pattern_name])
    if count > 0:
        found_any = True
        print(f"{pattern_name}: {count} occurrence(s)")
        for fname, line_num, text in results[pattern_name]:
            print(f"  {fname}:{line_num}")
        print()

if not found_any:
    print("No blacklisted words/phrases found!")

